603:   function moveVector() {
604:     let x = stick.vx, y = stick.vy;
605:     const len = Math.hypot(x, y);
606:     if (len > .12) {
607:       const m = Math.min(1, len);
608:       return { x: x / len * m, y: y / len * m, len: m };
609:     }
610:     return keyMoveVector();
