617:     p.attackT = .3;
618:     p.attackCd = .36;
619:     p.attackHit = false;
620:     p.attackSide *= -1;
621:     // generous aim assist toward the closest threat
622:     let target = null, best = base * .62;
623:     if (G.boss && ['chase', 'slamWindup', 'slamRecover', 'chargeWindup', 'chargeRecover', 'volleyWindup', 'volleyRecover', 'fissureWindup', 'fissureRecover'].includes(G.boss.state)) {
624:       const d = distEnt(p, G.boss);
625:       if (d < best) { best = d; target = G.boss; }
626:     }
627:     for (const w of G.wisps) {
628:       const d = distEnt(p, w);
629:       if (d < best) { best = d; target = w; }
