782:   function spawnParticles(nxPos, nyPos, count, opts = {}) {
783:     const speed = opts.speed || base * .3;
784:     for (let i = 0; i < count; i++) {
785:       const a = opts.angle != null ? opts.angle + rand(.65, -.65) : rand(TAU);
786:       const sp = speed * rand(1.1, .18);
787:       const life = (opts.life || .8) * rand(1.2, .55);
788:       G.particles.push({
789:         x: nxPos, y: nyPos,
790:         vx: Math.cos(a) * sp / room.w,
791:         vy: Math.sin(a) * sp / room.h,
792:         life, max: life,
793:         size: (opts.size || 2) * rand(1.4, .6),
794:         color: opts.color || '#ffbd66',
795:         glow: !!opts.glow,
796:         gravity: (opts.gravity || 0) / room.h,
797:         drag: opts.drag == null ? .985 : opts.drag,
798:         alpha: opts.alpha == null ? 1 : opts.alpha,
799:         streak: !!opts.streak,
800:       });
801:     }
802:   }
803:   function spawnDust(nxPos, nyPos, count = 8) {
804:     spawnParticles(nxPos, nyPos, count, {
805:       color: '#8e7d63', speed: base * .18, life: .9, size: 6, gravity: -base * .04, alpha: .16, drag: .94,
806:     });
807:   }
808:   function screenShake(amount) { G.shake = Math.max(G.shake, amount); }
809: 
810:   function updateParticles(dt) {
811:     for (let i = G.particles.length - 1; i >= 0; i--) {
812:       const p = G.particles[i];
813:       p.life -= dt;
814:       if (p.life <= 0) { G.particles.splice(i, 1); continue; }
815:       p.vy += p.gravity * dt;
816:       p.vx *= Math.pow(p.drag, dt * 60);
817:       p.vy *= Math.pow(p.drag, dt * 60);
818:       p.x += p.vx * dt;
819:       p.y += p.vy * dt;
820:     }
821:     for (let i = G.decals.length - 1; i >= 0; i--) {
822:       G.decals[i].life -= dt;
823:       if (G.decals[i].life <= 0) G.decals.splice(i, 1);
824:     }
825:     for (let i = G.afterimages.length - 1; i >= 0; i--) {
826:       G.afterimages[i].life -= dt;
827:       if (G.afterimages[i].life <= 0) G.afterimages.splice(i, 1);
828:     }
829:     for (let i = G.slashes.length - 1; i >= 0; i--) {
830:       G.slashes[i].life -= dt;
831:       if (G.slashes[i].life <= 0) G.slashes.splice(i, 1);
832:     }
833:     for (const a of G.ambient) {
834:       a.x += a.vx * dt;
835:       a.y += a.vy * dt;
836:       a.ph += dt * 2;
837:       if (a.y < -.02) { a.y = 1.02; a.x = rand(1); }
838:       if (a.x < -.02) a.x = 1.02;
839:       if (a.x > 1.02) a.x = -.02;
840:     }
841:     for (const m of G.motes) {
842:       m.x += m.vx * dt;
843:       m.y += m.vy * dt;
844:       m.ph += dt;
845:       if (m.y > 1.02) { m.y = -.02; m.x = rand(1); }
846:       if (m.x < -.02) m.x = 1.02;
847:       if (m.x > 1.02) m.x = -.02;
848:     }
849:   }
