856:   function updatePlayer(dt) {
857:     const p = G.player;
858:     if (!p || !p.alive) return;
859:     p.attackCd = Math.max(0, p.attackCd - dt);
860:     p.rollCd = Math.max(0, p.rollCd - dt);
861:     p.inv = Math.max(0, p.inv - dt);
862:     p.hurtT = Math.max(0, p.hurtT - dt);
863:     const mv = moveVector();
864:     p.moving = mv.len > .02;
865: 
866:     if (p.rollT > 0) {
867:       p.rollT -= dt;
868:       const speed = base * 1.02;
869:       moveEnt(p, p.rollAng, speed, dt);
870:       if (Math.random() < dt * 28) {
871:         G.afterimages.push({ x: p.x, y: p.y, facing: p.facing, life: .2, max: .2, alpha: .35 });
872:       }
873:       spawnParticles(p.x, p.y, 1, {
874:         color: '#b9a47c', speed: base * .12, life: .35, size: 3, gravity: 0, alpha: .18,
875:       });
876:     } else {
877:       let speed = base * .34;
878:       if (p.attackT > 0) speed *= .42;
879:       if (p.moving) {
880:         moveEnt(p, Math.atan2(mv.y, mv.x), speed, dt);
881:         p.facing = Math.atan2(mv.y, mv.x);
882:         p.walk += dt * 10;
883:         p.footT -= dt;
884:         if (p.footT <= 0) {
