908:     // collision with pots & chest
909:     const pr = playerRadius();
910:     for (const pot of G.pots) {
911:       if (pot.dead) continue;
912:       const d = distEnt(p, pot);
913:       const rr = pr + base * .025;
914:       if (d < rr && d > .001) {
915:         const a = angleTo(pot, p);
916:         p.x = pot.x + Math.cos(a) * rr / room.w;
917:         p.y = pot.y + Math.sin(a) * rr / room.h;
918:       }
