929:     // boss body collision
930:     if (G.boss && G.boss.state !== 'dormant' && G.boss.state !== 'dying' && G.boss.state !== 'awaken') {
931:       const d = distEnt(p, G.boss);
932:       const bR = base * .068;
933:       const rr = pr + bR;
934:       if (d < rr && d > .001) {
935:         const a = angleTo(G.boss, p);
936:         p.x = G.boss.x + Math.cos(a) * rr / room.w;
937:         p.y = G.boss.y + Math.sin(a) * rr / room.h;
