950:   function performSwordHit() {
951:     const p = G.player;
952:     const reach = base * .115;
953:     const arc = 1.15;
954:     let hitSomething = false;
955: 
956:     for (let i = 0; i < G.pots.length; i++) {
957:       const pot = G.pots[i];
