969:       if (w.dying) continue;
970:       const d = distEnt(p, w);
971:       const a = angleTo(p, w);
972:       if (d < reach + base * .04 && Math.abs(angleDiff(a, p.facing)) < arc + .2) {
973:         w.hp -= 1;
974:         w.flash = .12;
975:         hitSomething = true;
976:         spawnParticles(w.x, w.y - .02, 12, {
977:           color: choose(['#ffb75d', '#ff6d30', '#ffe5a0']), speed: base * .42, life: .5,
978:           size: 2, glow: true, gravity: base * .1,
