981:           w.dying = .5;
982:           w.life = .5;
983:           spawnParticles(w.x, w.y - .02, 24, {
984:             color: choose(['#ffbf5f', '#b53e1f', '#ffe9ad']), speed: base * .55, life: .85,
985:             size: 2.4, glow: true, gravity: base * .1,
