996:     if (G.boss) {
997:       const b = G.boss;
998:       const d = distEnt(p, b);
999:       const a = angleTo(p, b);
1000:       if (d < reach + base * .075 && Math.abs(angleDiff(a, p.facing)) < arc + .35) {
1001:         if (['chase', 'slamWindup', 'slamRecover', 'chargeWindup', 'charge', 'chargeRecover', 'volleyWindup', 'volleyRecover', 'fissureWindup', 'fissureRecover'].includes(b.state)) {
1002:           damageBoss(4.1 + Math.random() * .55, 'sword');
1003:           hitSomething = true;
1004:         }
