1010:         x: p.x, y: p.y, facing: p.facing, side: p.attackSide,
1011:         life: .18, max: .18, hit: true,
1012:       });
1013:     } else {
1014:       G.slashes.push({
1015:         x: p.x, y: p.y, facing: p.facing, side: p.attackSide,
