1118:   function updateBoss(dt) {
1119:     const b = G.boss;
1120:     if (!b) return;
1121:     b.flash = Math.max(0, b.flash - dt);
1122:     b.hurtKick = Math.max(0, (b.hurtKick || 0) - dt * 5);
1123:     b.t += dt;
1124: 
1125:     if (G.progress === 'won' || b.state === 'dying') {
1126:       b.dying += dt;
1127:       if (b.state !== 'dying') b.state = 'dying';
1128:       b.bob += dt;
1129:       if (b.dying > .18 && Math.random() < dt * 22) {
1130:         spawnParticles(b.x + rand(.05, -.05), b.y - rand(.15, .02), 1, {
1131:           color: choose(['#ffb75b', '#d24d26', '#ffe7a6']), speed: base * .25, life: .9,
1132:           size: rand(2.8, 1.2), glow: true, gravity: -base * .04,
1133:         });
1134:       }
1135:       if (b.dying > 1.1 && !b.burst) {
1136:         b.burst = true;
1137:         G.shake = 14;
1138:         spawnParticles(b.x, b.y - .09, 64, {
1139:           color: choose(['#ffd77c', '#ff7c32', '#eae2c8', '#9f2e1b']), speed: base * .72,
1140:           life: 1.7, size: 3, glow: true, gravity: base * .13,
1141:         });
1142:         audio.slam();
1143:       }
1144:       if (b.dying > 2.6 && G.state === 'playing') {
1145:         G.state = 'victory';
1146:         showEnd(true);
1147:       }
1148:       return;
1149:     }
1150: 
1151:     if (b.state === 'dormant') {
1152:       b.weapon = lerp(b.weapon, -.5, Math.min(1, dt * 2));
1153:       return;
1154:     }
1155: 
1156:     if (b.state === 'awaken') {
1157:       b.roar = Math.min(1, b.roar + dt * 2);
1158:       b.weapon = lerp(b.weapon, -1.7, Math.min(1, dt * 5));
1159:       G.shake = Math.max(G.shake, 8 * (1 - b.t / 2.2));
1160:       if (b.t > 1.9) {
1161:         b.state = 'chase';
1162:         b.t = 0;
1163:         b.cd = 1.0;
1164:         b.roar = 0;
1165:         G.progress = 'boss';
1166:         setObjective('Defeat the Cinder Warden');
1167:       }
1168:       return;
1169:     }
1170: 
1171:     if (b.state === 'phaseTransition') {
1172:       b.weapon = lerp(b.weapon, -1.9, Math.min(1, dt * 6));
1173:       if (b.t > 1.2) {
1174:         b.state = 'chase';
1175:         b.t = 0;
1176:         b.cd = .6;
1177:       }
1178:       return;
1179:     }
1180: 
1181:     if (b.stun > 0) {
1182:       b.stun -= dt;
1183:       b.weapon = lerp(b.weapon, 1.35, Math.min(1, dt * 7));
1184:       if (b.stun <= 0) {
1185:         b.state = 'chase';
1186:         b.t = 0;
1187:         b.cd = .4;
1188:       }
1189:       return;
1190:     }
1191: 
1192:     const p = G.player;
1193:     const dist = distEnt(b, p);
1194:     const ang = angleTo(b, p);
1195:     const speed = base * (.13 + b.phase * .013);
1196: 
1197:     switch (b.state) {
1198:       case 'chase': {
1199:         b.face = p.x < b.x ? -1 : 1;
1200:         b.cd -= dt;
1201:         const strafe = Math.sin(G.time * 1.7) * .33;
1202:         if (dist > base * .205) {
1203:           moveEnt(b, ang + strafe * .22, speed, dt);
1204:         } else if (dist < base * .13) {
1205:           moveEnt(b, ang + Math.PI + strafe * .15, speed * .7, dt);
1206:         } else {
1207:           moveEnt(b, ang + Math.PI / 2 * Math.sign(Math.sin(G.time * .9)) * .3, speed * .4, dt);
1208:         }
1209:         b.weapon = lerp(b.weapon, -.5 + Math.sin(G.time * 2) * .07, Math.min(1, dt * 4));
1210:         if (b.cd <= 0 && b.t > .35) {
1211:           chooseBossAttack(dist);
1212:         }
1213:         break;
1214:       }
1215:       case 'slamWindup': {
1216:         if (b.t < .48) b.face = p.x < b.x ? -1 : 1;
1217:         b.weapon = lerp(b.weapon, -2.15, Math.min(1, dt * 8));
1218:         if (b.t > .78) doSlam();
1219:         break;
1220:       }
1221:       case 'slamRecover': {
1222:         b.weapon = lerp(b.weapon, 1.05, Math.min(1, dt * 9));
1223:         if (b.t > .6) { b.state = 'chase'; b.t = 0; b.cd = b.phase > 2 ? .55 : .9; }
1224:         break;
1225:       }
1226:       case 'chargeWindup': {
1227:         if (b.t < .5) { b.ang = ang; b.face = p.x < b.x ? -1 : 1; }
1228:         b.weapon = lerp(b.weapon, .3, Math.min(1, dt * 5));
1229:         if (b.t > .72) {
1230:           b.state = 'charge';
1231:           b.t = 0;
1232:           b.chargeAng = b.ang;
1233:           audio.charge();
1234:           G.shake = 5;
1235:         }
1236:         break;
1237:       }
1238:       case 'charge': {
1239:         moveEnt(b, b.chargeAng, base * (1.12 + b.phase * .08), dt);
1240:         b.weapon = .55;
1241:         spawnDust(b.x, b.y, 1);
1242:         if (dist < bossRadius() + playerRadius() + 4) hurtPlayer(1);
1243:         const bx = b.x, by = b.y;
1244:         clampEnt(b, bossRadius(), .02);
1245:         if (b.t > .7 || Math.abs(bx - b.x) < .0001 && Math.abs(by - b.y) < .0001) {
1246:           b.state = 'chargeRecover';
1247:           b.stun = .95;
1248:           b.t = 0;
1249:           G.shake = 11;
1250:           audio.slam();
1251:           spawnParticles(b.x, b.y, 26, {
1252:             color: '#8b7658', speed: base * .5, life: .9, size: 3.2, gravity: base * .4, alpha: .5,
1253:           });
1254:           for (let i = 0; i < G.pots.length; i++) {
1255:             if (!G.pots[i].dead && distEnt(b, G.pots[i]) < base * .12) breakPot(i);
1256:           }
1257:         }
1258:         break;
1259:       }
1260:       case 'chargeRecover': {
1261:         if (b.t > .25) { b.state = 'chase'; b.t = 0; b.cd = .55; }
1262:         break;
1263:       }
1264:       case 'volleyWindup': {
1265:         b.face = p.x < b.x ? -1 : 1;
1266:         b.weapon = lerp(b.weapon, -.9, Math.min(1, dt * 6));
1267:         if (b.t > .72) doVolley();
1268:         break;
1269:       }
1270:       case 'volleyRecover': {
1271:         b.weapon = lerp(b.weapon, -.4, Math.min(1, dt * 5));
1272:         if (b.t > .55) { b.state = 'chase'; b.t = 0; b.cd = 1.0; }
1273:         break;
1274:       }
1275:       case 'fissureWindup': {
1276:         b.weapon = lerp(b.weapon, -1.55, Math.min(1, dt * 5));
1277:         b.targetX = p.x; b.targetY = p.y;
1278:         if (b.t > .8) doFissure();
1279:         break;
1280:       }
1281:       case 'fissureRecover': {
1282:         b.weapon = lerp(b.weapon, -.5, Math.min(1, dt * 5));
1283:         if (b.t > .75) { b.state = 'chase'; b.t = 0; b.cd = 1.0; }
1284:         break;
1285:       }
1286:     }
1287:     b.bob += dt * (b.state === 'chase' ? 4 : 1.5);
1288:     clampEnt(b, bossRadius(), .025);
1289:   }
