2219:   function drawBanner(x, top, w, bottom, flip) {
2220:     ctx.save();
2221:     ctx.translate(x, top);
2222:     const sway = Math.sin(G.time * .6 + x * .01) * 2.5;
2223:     const h = bottom - top;
2224:     ctx.beginPath();
2225:     ctx.moveTo(-w / 2, 0);
2226:     ctx.lineTo(w / 2, 0);
2227:     ctx.quadraticCurveTo(w / 2 + sway, h * .48, w * .38 + sway, h * .88);
2228:     ctx.lineTo(w * .12 + sway, h);
2229:     ctx.lineTo(0, h * .86);
2230:     ctx.lineTo(-w * .12 + sway, h);
2231:     ctx.lineTo(-w * .38 + sway, h * .88);
2232:     ctx.quadraticCurveTo(-w / 2 + sway, h * .48, -w / 2, 0);
2233:     ctx.closePath();
2234:     const g = ctx.createLinearGradient(-w / 2, 0, w / 2, 0);
2235:     g.addColorStop(0, '#251b19');
2236:     g.addColorStop(.25, '#4f2624');
2237:     g.addColorStop(.55, '#642e29');
2238:     g.addColorStop(.8, '#35201e');
2239:     g.addColorStop(1, '#1c1513');
2240:     ctx.fillStyle = g;
2241:     ctx.fill();
2242:     ctx.strokeStyle = 'rgba(177,132,67,.29)';
2243:     ctx.lineWidth = 1;
2244:     ctx.stroke();
2245:     // emblem
2246:     ctx.translate(sway * .3, h * .32);
2247:     ctx.strokeStyle = 'rgba(214,167,86,.4)';
2248:     ctx.lineWidth = 1.2;
2249:     ctx.beginPath(); ctx.arc(0, 0, w * .19, 0, TAU); ctx.stroke();
2250:     ctx.beginPath();
2251:     ctx.moveTo(0, -w * .19); ctx.lineTo(w * .08, 0); ctx.lineTo(0, w * .19); ctx.lineTo(-w * .08, 0); ctx.closePath();
2252:     ctx.stroke();
2253:     // wear
2254:     ctx.fillStyle = 'rgba(20,10,8,.3)';
2255:     for (let i = 0; i < 11; i++) {
2256:       ctx.fillRect(-w / 2 + (i * 31 % w), h * ((i * .173) % .95), 2, 10 + i * 3);
2257:     }
2258:     ctx.restore();
2259:   }
