2268:   function buildWallCache() {
2269:     if (W < 2 || H < 2) { wallCache = null; return; }
2270:     const c = document.createElement('canvas');
2271:     c.width = Math.max(1, Math.round(W * DPR));
2272:     c.height = Math.max(1, Math.round(H * DPR));
2273:     const g = c.getContext('2d');
2274:     g.setTransform(DPR, 0, 0, DPR, 0, 0);
2275:     const prev = ctx;
2276:     ctx = g;
2277:     wallCaching = true;
2278:     try { drawWalls(); } finally { wallCaching = false; ctx = prev; }
2279:     wallCache = c;
2280:   }
