2313:       for (let i = 0; i < 8; i++) {
2314:         const rx = (rng() - .5) * 37 * s;
2315:         const ry = (rng() - .5) * 12 * s;
2316:         const rw = (6 + rng() * 11) * s;
2317:         const rh = (4 + rng() * 7) * s;
2318:         ctx.save();
2319:         ctx.translate(rx, ry);
2320:         ctx.rotate(rng() * 3);
2321:         const g = ctx.createLinearGradient(0, -rh, 0, rh);
2322:         g.addColorStop(0, '#555043');
2323:         g.addColorStop(.5, '#3a352c');
2324:         g.addColorStop(1, '#1a1814');
2325:         ctx.fillStyle = g;
2326:         ctx.beginPath();
2327:         ctx.moveTo(-rw * .5, -rh * .3);
2328:         ctx.lineTo(-rw * .2, -rh * .7);
2329:         ctx.lineTo(rw * .42, -rh * .42);
2330:         ctx.lineTo(rw * .52, rh * .25);
2331:         ctx.lineTo(-rw * .15, rh * .55);
2332:         ctx.lineTo(-rw * .55, rh * .15);
