2335:         ctx.restore();
2336:       }
2337:       // old bones curled among the stones
2338:       if (cl.seed % 2) {
2339:         ctx.strokeStyle = 'rgba(181,168,137,.27)';
2340:         ctx.lineWidth = 2.1 * s;
2341:         ctx.lineCap = 'round';
2342:         ctx.beginPath(); ctx.moveTo(8 * s, -3 * s); ctx.quadraticCurveTo(19 * s, -9 * s, 26 * s, -2 * s); ctx.stroke();
2343:         for (let i = 0; i < 4; i++) {
2344:           ctx.fillStyle = 'rgba(185,171,139,.25)';
2345:           ctx.beginPath(); ctx.arc((14 + i * 3) * s, (-7 + Math.sin(i) * 1.5) * s, 2.1 * s, 0, TAU); ctx.fill();
2346:         }
2347:       }
