2349:       ctx.fillStyle = 'rgba(55,73,41,.2)';
2350:       for (let i = 0; i < 4; i++) {
2351:         ellipse(ctx, (rng() - .5) * 38 * s, (rng() - .3) * 8 * s, 7 * s, 3 * s, rng() * 2);
