2698:   function drawBarrier() {
2699:     const gate = G.gate;
2700:     if (gate.open && !gate.unlocking) return;
2701:     let opacity = 1;
2702:     if (gate.unlocking) opacity = clamp(1 - gate.t / 1.3, 0, 1);
2703:     if (opacity <= 0) return;
2704:     const y = py(gate.y);
2705:     const x0 = px(.105), x1 = px(.895);
2706:     const hh = clamp(base * .165, 62, 120);
2707:     const t = G.time;
2708:     const width = x1 - x0;
2709:     ctx.save();
2710:     ctx.globalAlpha = opacity;
2711: 
2712:     // the floor is scorched where the seal touches it
2713:     const scorch = ctx.createRadialGradient((x0 + x1) / 2, y, width * .1, (x0 + x1) / 2, y, width * .62);
2714:     scorch.addColorStop(0, 'rgba(255,129,43,.13)');
2715:     scorch.addColorStop(.55, 'rgba(115,52,24,.08)');
2716:     scorch.addColorStop(1, 'rgba(0,0,0,0)');
2717:     ctx.fillStyle = scorch;
2718:     ctx.fillRect(x0 - 20, y - 8, width + 40, 34);
2719: 
2720:     // a faint veil
2721:     const veil = ctx.createLinearGradient(0, y - hh, 0, y + 2);
2722:     veil.addColorStop(0, 'rgba(255,213,130,0)');
2723:     veil.addColorStop(.35, 'rgba(255,187,82,.045)');
2724:     veil.addColorStop(.72, 'rgba(255,132,43,.11)');
2725:     veil.addColorStop(.95, 'rgba(255,183,84,.24)');
2726:     veil.addColorStop(1, 'rgba(255,110,35,.04)');
2727:     ctx.fillStyle = veil;
2728:     ctx.fillRect(x0, y - hh, width, hh + 4);
2729: 
2730:     // a tangible sheet of old fire, with a breathing upper edge
2731:     ctx.globalCompositeOperation = 'source-over';
2732:     const sheet = ctx.createLinearGradient(0, y - hh, 0, y);
2733:     sheet.addColorStop(0, 'rgba(255,205,118,.025)');
2734:     sheet.addColorStop(.28, 'rgba(255,173,69,.06)');
2735:     sheet.addColorStop(.68, 'rgba(255,130,42,.13)');
2736:     sheet.addColorStop(.94, 'rgba(255,188,82,.23)');
2737:     sheet.addColorStop(1, 'rgba(255,104,36,.07)');
2738:     ctx.fillStyle = sheet;
2739:     ctx.beginPath();
2740:     ctx.moveTo(x0, y);
2741:     for (let xx = x0; xx <= x1; xx += 11) {
2742:       const top = y - hh * (.78 + Math.sin(xx * .035 + t * 2.2) * .055 + Math.sin(xx * .11 - t * 3) * .025);
2743:       if (xx === x0) ctx.lineTo(xx, top); else ctx.lineTo(xx, top);
2744:     }
2745:     ctx.lineTo(x1, y);
2746:     ctx.closePath();
2747:     ctx.fill();
2748:     ctx.strokeStyle = 'rgba(255,212,127,.23)';
2749:     ctx.lineWidth = 1.2;
2750:     ctx.beginPath();
2751:     for (let xx = x0; xx <= x1; xx += 10) {
2752:       const top = y - hh * (.78 + Math.sin(xx * .035 + t * 2.2) * .055 + Math.sin(xx * .11 - t * 3) * .025);
2753:       if (xx === x0) ctx.moveTo(xx, top); else ctx.lineTo(xx, top);
2754:     }
2755:     ctx.stroke();
2756: 
2757:     ctx.globalCompositeOperation = 'lighter';
2758:     // rising tongues of flame, evenly spaced but alive
2759:     const tongues = 22;
2760:     for (let i = 0; i < tongues; i++) {
2761:       const xx = x0 + ((i + .5) / tongues) * width;
2762:       const ph = t * (1.3 + (i % 4) * .19) + i * 1.83;
2763:       const h = hh * (.3 + .5 * (0.5 + Math.sin(ph * 1.21 + i) * .5));
2764:       const sway = Math.sin(ph) * 7;
2765:       const fg = ctx.createLinearGradient(xx, y - h, xx, y);
2766:       fg.addColorStop(0, 'rgba(255,234,167,0)');
2767:       fg.addColorStop(.42, `rgba(255,169,64,${.055 + .04 * (0.5 + Math.sin(ph) * .5)})`);
2768:       fg.addColorStop(.92, 'rgba(255,223,156,.27)');
2769:       fg.addColorStop(1, 'rgba(255,128,44,.04)');
2770:       ctx.fillStyle = fg;
2771:       ctx.beginPath();
2772:       ctx.moveTo(xx - 5, y);
2773:       ctx.bezierCurveTo(xx - 9 + sway, y - h * .42, xx + sway * .4, y - h * .78, xx + sway * 1.2, y - h);
2774:       ctx.bezierCurveTo(xx + 8 + sway * .2, y - h * .58, xx + 8, y - h * .24, xx + 5, y);
2775:       ctx.closePath();
2776:       ctx.fill();
2777:     }
2778: 
2779:     // thin veil threads
2780:     for (let i = 0; i < 13; i++) {
2781:       const xx = x0 + ((i * 79 + 23) % width);
2782:       const ph = t * (1.1 + (i % 3) * .22) + i * 2.1;
2783:       const off = Math.sin(ph) * 6;
2784:       ctx.strokeStyle = `rgba(255,205,119,${.035 + .05 * (0.5 + Math.sin(ph * 1.8) * .5)})`;
2785:       ctx.lineWidth = 1;
2786:       ctx.beginPath();
2787:       ctx.moveTo(xx + off * .2, y - hh * .22);
2788:       ctx.bezierCurveTo(xx + off, y - hh * .5, xx - off, y - hh * .76, xx + off * .3, y);
2789:       ctx.stroke();
2790:     }
2791: 
2792:     // warding bands with glyphs
2793:     for (let b = 0; b < 3; b++) {
2794:       const yy = y - hh * (.42 + b * .16);
2795:       ctx.strokeStyle = `rgba(255,209,124,${.22 - b * .04})`;
2796:       ctx.lineWidth = 1;
2797:       ctx.beginPath();
2798:       for (let xx = x0; xx <= x1; xx += 14) {
2799:         const wave = Math.sin(xx * .035 + t * 1.6 + b * 2) * (2.5 + b);
2800:         if (xx === x0) ctx.moveTo(xx, yy + wave); else ctx.lineTo(xx, yy + wave);
2801:       }
2802:       ctx.stroke();
2803:       for (let i = 0; i < 8; i++) {
2804:         const xx = x0 + ((i + .5) / 8) * width;
2805:         const wave = Math.sin(xx * .035 + t * 1.6 + b * 2) * (2.5 + b);
2806:         ctx.save();
2807:         ctx.translate(xx, yy + wave);
2808:         ctx.rotate(Math.PI / 4 + Math.sin(t * 1.2 + i + b) * .09);
2809:         ctx.strokeStyle = `rgba(255,221,145,${.28 - b * .05})`;
2810:         ctx.lineWidth = 1;
2811:         const sz = 2.5 + b * .7;
2812:         ctx.strokeRect(-sz, -sz, sz * 2, sz * 2);
2813:         ctx.restore();
2814:       }
2815:     }
2816: 
2817:     // rising motes
2818:     for (let i = 0; i < 18; i++) {
2819:       const ph = t * (.55 + (i % 5) * .1) + i * 3.2;
2820:       const xx = x0 + ((i + .3) / 18) * width + Math.sin(ph) * 10;
2821:       const yy = y - ((t * (30 + (i % 4) * 9) + i * 17) % hh);
2822:       const a = .16 + .22 * (0.5 + Math.sin(ph * 2) * .5);
2823:       ctx.fillStyle = `rgba(255,188,92,${a})`;
2824:       ctx.beginPath(); ctx.arc(xx, yy, .9 + (i % 2) * .8, 0, TAU); ctx.fill();
2825:     }
2826: 
2827:     // the bright hem where the spell bites the stone
2828:     const baseG = ctx.createLinearGradient(0, y - 6, 0, y + 8);
2829:     baseG.addColorStop(0, 'rgba(255,243,199,.5)');
2830:     baseG.addColorStop(.3, 'rgba(255,190,92,.47)');
2831:     baseG.addColorStop(1, 'rgba(255,92,31,0)');
2832:     ctx.fillStyle = baseG;
2833:     ctx.fillRect(x0, y - 6, width, 14);
2834:     ctx.strokeStyle = 'rgba(255,241,188,.6)';
2835:     ctx.lineWidth = 1.2;
2836:     ctx.beginPath();
2837:     for (let xx = x0; xx <= x1; xx += 10) {
2838:       const wave = Math.sin(xx * .06 + t * 3) * 1.1;
2839:       if (xx === x0) ctx.moveTo(xx, y + wave); else ctx.lineTo(xx, y + wave);
2840:     }
2841:     ctx.stroke();
2842:     ctx.restore();
2843:   }
