2869:       ctx.rotate(rp * 7 + p.rollAng);
2870:       ctx.scale(PS, PS);
2871:       const cg = ctx.createRadialGradient(0, -16, 2, 0, -16, 20);
2872:       cg.addColorStop(0, '#3d8980');
2873:       cg.addColorStop(.7, '#1e4b4a');
