2878:       ctx.lineWidth = 2;
2879:       ctx.beginPath(); ctx.arc(0, -14, 12, .3, 3.8); ctx.stroke();
2880:       ctx.fillStyle = '#e4c37e';
2881:       ctx.beginPath(); ctx.arc(7, -17, 2.2, 0, TAU); ctx.fill();
2882:       ctx.restore();
2883:       ctx.restore();
2884:       return;
2885:     }
2886: 
2887:     const bob = p.moving ? Math.sin(p.walk * 2) * 1.4 : Math.sin(t * 2.1) * .7;
2888:     ctx.translate(0, bob);
2889:     const faceDir = Math.cos(p.facing) >= 0 ? 1 : -1;
2890: 
2891:     // cloak / cape
2892:     const sway = Math.sin(t * 5.2) * 1.3 + (p.moving ? Math.sin(p.walk * 2) * 1.4 : 0);
2893:     ctx.save();
2894:     ctx.scale(faceDir, 1);
2895:     const cloak = ctx.createLinearGradient(0, -44 * PS, 0, -2 * PS);
2896:     cloak.addColorStop(0, '#2b6f69');
2897:     cloak.addColorStop(.5, '#1e4e4d');
2898:     cloak.addColorStop(1, '#102c2d');
2899:     ctx.fillStyle = cloak;
2900:     ctx.beginPath();
2901:     ctx.moveTo(-9 * PS, -43 * PS);
2902:     ctx.quadraticCurveTo(-20 * PS, -30 * PS, -17 * PS + sway, -8 * PS);
2903:     ctx.lineTo(-13 * PS + sway, -2 * PS);
2904:     ctx.lineTo(-6 * PS, -5 * PS);
2905:     ctx.lineTo(0, -1 * PS);
2906:     ctx.lineTo(7 * PS, -5 * PS);
2907:     ctx.lineTo(14 * PS + sway, -2 * PS);
2908:     ctx.lineTo(18 * PS + sway, -10 * PS);
2909:     ctx.quadraticCurveTo(19 * PS, -31 * PS, 9 * PS, -43 * PS);
2910:     ctx.closePath();
2911:     ctx.fill();
2912:     ctx.strokeStyle = 'rgba(118,177,158,.27)';
2913:     ctx.lineWidth = 1;
2914:     ctx.stroke();
2915:     ctx.restore();
2916: 
2917:     // legs
2918:     const step = p.moving ? Math.sin(p.walk * 2) : 0;
2919:     for (const side of [-1, 1]) {
2920:       const lx = side * 5.2 * PS;
2921:       const ly = -10 * PS + (side * step * 2.2 * PS);
2922:       ctx.fillStyle = side === -1 ? '#231f19' : '#2c261f';
2923:       roundedRect(ctx, lx - 2.9 * PS, ly, 5.8 * PS, 11 * PS, 2.4 * PS); ctx.fill();
2924:       ctx.fillStyle = '#4d4436';
2925:       roundedRect(ctx, lx - 3.8 * PS, ly + 8.2 * PS, 7.8 * PS, 3.2 * PS, 1.5 * PS); ctx.fill();
